function scheduleVacation(s,slot){const year=Number(s.date.slice(0,4));const starts=[`${year}-06-07`,`${year}-07-05`,`${year}-08-02`,`${year}-09-06`];const base=starts[(slot-1)%4];for(let i=0;i<20;i++){const d=addWorkdays(addCalendarDays(base,-1),i+1);for(const e of s.employees){if(e.vacationPlan.length===20)continue;const offset=(STAFF.findIndex(p=>p.id===e.id)*5);if(i>=offset&&i<offset+5&&!e.vacationPlan.includes(d)){e.vacationPlan.push(d);e.vacationDaysUsed++;s.annualStats.vacationDays++;}}}}
